import org.apache.ibatis.annotations.Insert;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Update;

import com.itwillwork.itwillwork.model.Student;

@Mapper
public interface StudentMapper {

	@Select("SELECT * FROM student")
	List<Student> getStudents();

	@Select("SELECT * FROM student WHERE id = #{id}")
	Student getStudent(int id);

	@Insert("INSERT INTO student(name, age, gender, address) VALUES(#{name}, #{age}, #{gender}, #{address})")
	void addStudent(Student student);

	@Update("UPDATE student SET name = #{name}, age = #{age}, gender = #{gender}, address = #{address} WHERE id = #{id}")
	void updateStudent(Student student);

	@Delete("DELETE FROM student WHERE id = #{id}")
	void deleteStudent(int id);

}

